'use strict';
const shellTexts=['header','footer','#guide'].map(selector=>({selector,html:document.querySelector(selector).innerHTML}));
function changeLanguage(next){if(!['es','en'].includes(next))return;language=next;if(state.running){stopTimers();state.phase='paused';}document.documentElement?.setAttribute('lang',language==='en'?'en':'es-AR');document.title=language==='en'?'Tilo helps me':'Tilo me ayuda';shellTexts.forEach(({selector,html})=>document.querySelector(selector).innerHTML=translate(html));document.querySelectorAll?.('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===language)));render();}
const app=document.querySelector('#app');
let state={view:'home',stage:0,round:0,running:false,phase:'ready',answer:null,word:0,wordChoice:null,cards:[],flipped:[],matched:[],story:'enojo',page:0};
let breathTimer=null,memoryTimer=null;
const words=[{original:'¡Dámelo!',options:['¿Me lo prestás, por favor?','¡Es mío, dámelo ya!'],kind:0,feedback:'Podemos pedir lo que queremos sin gritar. La otra persona también puede decir que no.'},{original:'¡No sabés jugar!',options:['¡Siempre lo hacés mal!','¿Querés que lo intentemos juntos?'],kind:1,feedback:'Invitar a intentar juntos cuida más que burlarse. Todos podemos estar aprendiendo.'},{original:'¡Andate!',options:['Necesito un ratito de espacio, por favor.','¡No te quiero ver nunca!'],kind:0,feedback:'Podemos pedir espacio y contar lo que necesitamos sin lastimar.'}];
const characters={tilo:'tilo-modelo.png',luma:'luma.png',milo:'milo.png',chispita:'chispita.png'};
function picture(src='tilo-modelo.png',alt='Tilo, el elefante de barba roja',cls=''){return `<img class="character ${cls}" src="${src}" alt="${alt}">`;}
function button(text,action,cls='primary'){return `<button class="${cls}" data-action="${action}">${text}</button>`;}
function activityHeader(label,time='1–3 minutos'){return `<div class="top"><button class="back" data-action="home">Volver con Tilo</button><span class="duration">${time}</span></div><div class="center"><span class="badge">${label}</span>`;}
function stopTimers(){clearTimeout(breathTimer);clearTimeout(memoryTimer);breathTimer=null;memoryTimer=null;state.running=false;}
function open(view){if(!['home','anger','sadness','words','games','memory','stories','story','well'].includes(view))throw new Error('Actividad no válida');stopTimers();state={view,stage:0,round:0,running:false,phase:'ready',answer:null,word:0,wordChoice:null,cards:[],flipped:[],matched:[],story:'enojo',page:0};if(view==='memory'){state.cards=Object.keys(characters).flatMap(x=>[x,x]);for(let i=state.cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[state.cards[i],state.cards[j]]=[state.cards[j],state.cards[i]];}}render();}
function startStory(key){if(!Object.hasOwn(adventures,key))throw new Error('Cuento no válido');open('story');state.story=key;render();}
function render(){let html='';
if(state.view==='home'){html=`<div class="center">${picture('tilo-modelo.png','Tilo te saluda','home-tilo')}<h1>¿Cómo te sentís?</h1><p class="lead">Tocá un botón. Vamos de a poquito.</p></div><div class="feelings">${[['anger','😡','Estoy enojado','anger'],['sadness','😢','Estoy triste','sadness'],['miedo','😨','Tengo miedo','fear'],['enojo','😤','Estoy frustrado','frustration'],['well','😊','Estoy bien','well']].map(([key,emoji,label,color])=>`<button class="feeling ${color}" ${key==='miedo'||key==='enojo'?`data-story="${key}"`:`data-open="${key}"`}><span aria-hidden="true">${emoji}</span>${label}</button>`).join('')}</div><p class="tiny center">La respiración y la compañía son herramientas para practicar. Los cuentos también ayudan a conversar.</p><div class="navigation"><button data-open="home">Quiero calmarme<small>Respirar y acompañar</small></button><button data-open="words">Quiero aprender<small>Palabras que cuidan</small></button><button data-open="games">Quiero jugar<small>Con los amigos de Tilo</small></button><button data-open="stories">🎬 Cuentos de Tilo<small>Quiero ver un cuento</small></button></div>`;}
else if(state.view==='anger'){html=activityHeader('EL SUPERPODER DE LA CALMA');if(state.stage===0){html+=`<h1>Respiración de la trompa</h1>${picture()}<p class="lead">Estoy enojado. Puedo hacer una pausa.</p><p>Inspirá suave cuando el círculo crece.<br>Soltá el aire cuando se achica.</p><p class="tiny">A tu ritmo. Podés parar cuando quieras.</p><div class="actions">${button('Respirar con Tilo','start-breath')}${button('Prefiero pedir ayuda','anger-help','secondary')}</div>`;}else if(state.stage===1){html+=`<h1>Respiremos juntos</h1><div class="breath-zone"><div class="breath-ring ${state.phase==='in'?'expand':''}" aria-hidden="true"></div><img src="tilo-modelo.png" alt="Tilo acompaña la respiración"></div><p class="breath-cue" aria-live="polite">${state.phase==='in'?'Inspirá suavemente':state.phase==='out'?'Soltá el aire despacio':'Hacemos una pausa'}</p><p id="round-counter">Respiración ${Math.min(state.round+1,3)} de 3</p><div class="actions">${button(state.running?'Pausar':'Seguir respirando',state.running?'pause-breath':'resume-breath','secondary')}${button('Terminar la respiración','finish-breath','secondary')}</div>`;}else{html+=`<h1>¿Estás un poquito<br>más tranquilo?</h1>${picture()}<div class="actions">${button('Sí, un poquito','calmer')}${button('Todavía estoy enojado','still-angry','secondary')}</div>${state.answer?`<p class="feedback" aria-live="polite">${state.answer==='yes'?'Bien por hacer una pausa. Podés decir qué necesitás con palabras.':'Está bien. No hay que dejar de sentirlo enseguida. Buscá a una persona de confianza y pedile compañía.'}</p><div class="actions"><button class="secondary" data-story="enojo">Leer el cuento de la torre</button>${button('Volver con Tilo','home')}</div>`:''}`;}html+='</div>';}
else if(state.view==='sadness'){html=activityHeader('EL SUPERPODER DE ACOMPAÑAR');if(state.stage===0){html+=`<h1>No estás solo.</h1>${picture(language==='en'?'tilo-mano.png':'tilo-compania.png','Tilo abre sus brazos: No estás solo','sad-photo')}<p class="lead">Podés estar triste. No hace falta sonreír ahora.</p><p>¿Qué te gustaría probar?</p><div class="actions">${button('Un abrazo, si quiero','hug')}${button('Que alguien me acompañe','company','secondary')}${button('Un ratito de espacio','space','secondary')}</div>`;}else{const msg={hug:'Podés darte un abrazo suave como Tilo, o pedir uno a alguien. Solo si los dos quieren.',company:'Buscá a alguien de confianza. Podés decir: «Estoy triste, ¿te quedás conmigo?».',space:'Podés pedir: «Quiero estar en silencio un ratito». Una persona de confianza puede quedarse cerca.'};html+=`<h1>${state.answer==='hug'?'Un abrazo para vos.':'Hay lugar para tu tristeza.'}</h1>${picture(state.answer==='hug'?'tilo-abrazo.png':'tilo-mano.png',state.answer==='hug'?'Tilo se abraza':'Tilo ofrece compañía','sad-photo')}<p class="message">${msg[state.answer]}</p><p>No hace falta arreglarlo todo ahora.</p><div class="actions"><button class="secondary" data-story="tristeza">¿Leemos el cuento de Tilo y Luma?</button>${button('Ver el superpoder de Tilo','sad-video','secondary')}${button('Elegir otra ayuda','sad-again','secondary')}${button('Volver con Tilo','home')}</div>${state.stage===2?`<div class="video-wrap"><video controls playsinline preload="metadata" poster="tilo-mano.png" aria-label="Superpoder de Tilo sobre la tristeza"><source src="superpoder-tristeza.mp4" type="video/mp4"></video><p class="tiny">Miren el video juntos, si tienen ganas.</p></div>`:''}`;}html+='</div>';}
else if(state.view==='games'||state.view==='well'){html=activityHeader('JUGAR TAMBIÉN ES COMPARTIR');html+=`<h1>${state.view==='well'?'¡Qué lindo compartir!':'¿A qué querés jugar?'}</h1><div class="friends"><img src="milo.png" alt="Milo"><img src="luma.png" alt="Luma"><img src="chispita.png" alt="Chispita"></div><p class="lead">Elegí un juego con los amigos de Tilo.</p><div class="actions">${button('Encontrar a los amigos','memory')}${button('Palabras amables','words','secondary')}</div></div>`;}
else if(state.view==='words'){html=activityHeader('EL SUPERPODER DE LAS PALABRAS');if(state.word<words.length){const w=words[state.word];html+=`<h1>¿Cómo lo dirías<br>con cariño?</h1>${picture('toti.png','Toti, el tucán')}<div class="original">${w.original}</div><p>Elegí palabras que cuiden.</p><div class="actions">${w.options.map((t,i)=>`<button class="word-option ${state.wordChoice===i?'selected':''}" data-word="${i}" aria-pressed="${state.wordChoice===i}">${t}</button>`).join('')}</div>${state.wordChoice!==null?`<p class="feedback" aria-live="polite">${state.wordChoice===w.kind?w.feedback:'Probemos otra manera. Podemos decir lo que necesitamos sin gritar ni lastimar.'}</p>${state.wordChoice===w.kind?button('Otra frase','next-word'):''}`:''}<p class="tiny">Frase ${state.word+1} de 3</p>`;}else{html+=`<h1>Palabras que cuidan.</h1>${picture('toti.png','Toti')}<p class="message">Tu voz importa. Podés pedir, decir que no y contar lo que sentís con respeto.</p><div class="actions">${button('Jugar otra vez','words')}${button('Volver con Tilo','home','secondary')}</div>`;}html+='</div>';}
else if(state.view==='memory'){html=activityHeader('JUGAMOS CON LOS AMIGOS','A tu ritmo');html+=`<h1>Encontrá a los amigos.</h1><p>Tocá dos cartas. Buscá las parejas.</p><div class="memory">${state.cards.map((name,i)=>{const shown=state.flipped.includes(i)||state.matched.includes(i);return`<button data-card="${i}" class="${state.matched.includes(i)?'matched':''}" aria-label="${shown?name:'Carta '+(i+1)}" ${state.matched.includes(i)?'disabled':''}>${shown?`<img src="${characters[name]}" alt="${name}">`:'?'}</button>`;}).join('')}</div><p aria-live="polite">${state.matched.length===8?'¡Encontraste a todos!':'Parejas encontradas: '+state.matched.length/2+' de 4'}</p><div class="actions">${state.matched.length===8?button('Volver a jugar','memory'):''}${button('Elegir otro juego','games','secondary')}</div></div>`;}
else if(state.view==='stories'){html=activityHeader('🎬 CUENTOS DE TILO','Para compartir');html+=`<h1>Una historia para cada momento.</h1><p class="lead">Leé un cuento breve con tu familia.</p><div class="story-list">${Object.keys(adventures).map(key=>{const a=storyFor(key);return `<button class="story-card" data-story="${key}"><small>${a.label}</small><strong>${a.title}</strong></button>`;}).join('')}</div><div class="message"><strong>Un superpoder para ver juntos</strong><p>Ya podés ver el video de tristeza. Los demás videos se sumarán cuando estén listos.</p>${button('Ver el video de tristeza','video')}</div></div>`;}
else if(state.view==='story'){const a=storyFor(state.story);html=activityHeader('ADAPTACIÓN BREVE · LIBRO '+a.book);html+=`<h1>${a.title}</h1>${picture(state.story==='tristeza'?'luma.png':'tilo-modelo.png',state.story==='tristeza'?'Luma, la amiga tortuga de Tilo':'Tilo')}<p class="story-text">${a.story[state.page]}</p><p class="tiny">Página ${state.page+1} de 3</p><div class="actions">${state.page?button('Anterior','prev-story','secondary'):''}${state.page<2?button('Seguir el cuento','next-story'):''}${state.page===2?`<p class="message">${a.questions[0]}</p>${state.story==='tristeza'?button('Probar una ayuda con Tilo','sadness'):state.story==='enojo'?button('Respirar con la trompa','anger'):''}${button('Elegir otro cuento','stories','secondary')}`:''}</div></div>`;}
app.innerHTML=translate(html);const h=app.querySelector('h1');if(h){h.setAttribute('tabindex','-1');if(!state.running)h.focus({preventScroll:true});}}
function updateBreath(){const ring=document.querySelector('.breath-ring');if(ring)ring.classList.toggle('expand',state.phase==='in');const cue=document.querySelector('.breath-cue');if(cue)cue.textContent=translate(state.phase==='in'?'Inspirá suavemente':'Soltá el aire despacio');const counter=document.querySelector('#round-counter');if(counter)counter.textContent=translate('Respiración '+Math.min(state.round+1,3)+' de 3');}
function breathCycle(){if(state.view!=='anger'||!state.running)return;state.phase='in';updateBreath();breathTimer=setTimeout(()=>{if(state.view!=='anger'||!state.running)return;state.phase='out';updateBreath();breathTimer=setTimeout(()=>{if(state.view!=='anger'||!state.running)return;state.round++;if(state.round>=3){state.running=false;state.stage=2;state.phase='done';render();}else breathCycle();},5000);},4000);}
function breathe(){state.running=true;state.phase='ready';render();requestAnimationFrame(breathCycle);}
function flip(index){if(!Number.isInteger(index)||index<0||index>=8||state.flipped.includes(index)||state.matched.includes(index)||state.flipped.length>=2)return;state.flipped.push(index);if(state.flipped.length===2){const [a,b]=state.flipped;if(state.cards[a]===state.cards[b]){state.matched.push(a,b);state.flipped=[];}else memoryTimer=setTimeout(()=>{if(state.view==='memory'){state.flipped=[];render();}},1100);}render();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.language){changeLanguage(b.dataset.language);return;}if(b.dataset.open){open(b.dataset.open);return;}if(b.dataset.story){startStory(b.dataset.story);return;}if(b.dataset.word!==undefined&&state.view==='words'){state.wordChoice=Number(b.dataset.word);render();return;}if(b.dataset.card!==undefined&&state.view==='memory'){flip(Number(b.dataset.card));return;}switch(b.dataset.action){case'guide':document.querySelector('#guide').showModal();return;case'close-guide':document.querySelector('#guide').close();return;case'home':open('home');return;case'anger-help':state.stage=2;break;case'start-breath':case'resume-breath':state.stage=1;breathe();return;case'pause-breath':stopTimers();state.phase='paused';break;case'finish-breath':stopTimers();state.stage=2;break;case'calmer':state.answer='yes';break;case'still-angry':state.answer='no';break;case'hug':case'company':case'space':state.answer=b.dataset.action;state.stage=1;break;case'sad-again':state.stage=0;state.answer=null;break;case'sad-video':state.stage=2;break;case'video':open('sadness');state.stage=2;state.answer='company';break;case'next-word':if(state.wordChoice!==words[state.word]?.kind)return;state.word++;state.wordChoice=null;break;case'prev-story':state.page=Math.max(0,state.page-1);break;case'next-story':state.page=Math.min(2,state.page+1);break;case'words':case'memory':case'games':case'stories':case'anger':case'sadness':open(b.dataset.action);return;default:return;}render();});
window.addEventListener('pagehide',stopTimers);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_tilo_activity',description:'Abre una herramienta, juego o sección de cuentos de Tilo me ayuda. Reinicia la actividad actual.',inputSchema:{type:'object',properties:{activity:{type:'string',enum:['anger','sadness','words','games','memory','stories']}},required:['activity'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['anger','sadness','words','games','memory','stories'].includes(input.activity))throw new Error('Actividad no válida');open(input.activity);return{activity:state.view,started:true};}})).catch(()=>{});}catch{}}
